import {toast} from "react-toastify";
import React, {useEffect, useMemo, useRef, useState} from "react";
import {
    Alert,
    Box,
    Button,
    Divider,
    IconButton,
    MenuItem,
    Paper,
    Stack,
    TextField,
    Tooltip,
    Typography,
} from "@mui/material";
import AddPhotoAlternateOutlinedIcon from "@mui/icons-material/AddPhotoAlternateOutlined";
import ArrowBackOutlinedIcon from "@mui/icons-material/ArrowBackOutlined";
import ContentCopyOutlinedIcon from "@mui/icons-material/ContentCopyOutlined";
import DeleteOutlineOutlinedIcon from "@mui/icons-material/DeleteOutlineOutlined";
import DragIndicatorOutlinedIcon from "@mui/icons-material/DragIndicatorOutlined";
import HorizontalRuleOutlinedIcon from "@mui/icons-material/HorizontalRuleOutlined";
import NotesOutlinedIcon from "@mui/icons-material/NotesOutlined";
import ReceiptLongOutlinedIcon from "@mui/icons-material/ReceiptLongOutlined";
import SaveOutlinedIcon from "@mui/icons-material/SaveOutlined";
import TableRowsOutlinedIcon from "@mui/icons-material/TableRowsOutlined";
import TextFieldsOutlinedIcon from "@mui/icons-material/TextFieldsOutlined";
import {useNavigate, useParams} from "react-router-dom";
import {
    OfferTemplateDocument,
    OfferTemplateElement,
    OfferTemplateElementType,
} from "../../models/commercialOffer";
import {
    MainDiv,
    PageHeader,
    PageSubtitle,
    PageTitle,
    PageTitleGroup,
} from "../../ui/commonStyled/commonStyled";
import {
    useCreateCommercialOfferTemplateMutation,
    useGetCommercialOfferTemplateQuery,
    useUpdateCommercialOfferTemplateMutation,
} from "./commercialOffersApi";
import {
    createDefaultOfferTemplate,
    createPaletteElement,
    resolveSampleText,
    sampleBindingValues,
} from "./offerTemplateDefaults";

const CANVAS_SCALE = 0.82;

const elementLabels: Record<OfferTemplateElementType, string> = {
    text: "Текст",
    image: "Изображение",
    lineItems: "Таблица позиций",
    total: "Итого",
    conditions: "Условия",
    divider: "Разделитель",
};

const bindings = [
    ["", "Статический текст"],
    ["offer.number", "Номер КП"],
    ["offer.version", "Версия"],
    ["offer.issuedAt", "Дата выпуска"],
    ["offer.validUntil", "Действует до"],
    ["offer.total", "Итоговая сумма"],
    ["offer.vatTotal", "Сумма НДС"],
    ["offer.currency", "Валюта"],
    ["offer.notes", "Примечание"],
    ["customer.name", "Название клиента"],
    ["customer.contact", "Контакт клиента"],
    ["customer.email", "Email клиента"],
    ["customer.taxNumber", "УНП клиента"],
    ["customer.contract", "Договор клиента"],
    ["seller.name", "Компания-продавец"],
    ["seller.contact", "Контакты продавца"],
    ["manager", "Менеджер"],
    ["paymentTerms", "Условия оплаты"],
    ["deliveryTerms", "Условия доставки"],
];

const clamp = (value: number, min: number, max: number) => Math.min(max, Math.max(min, value));
const snap = (value: number) => Math.round(value / 2) * 2;

const ElementPreview = ({element}: {element: OfferTemplateElement}) => {
    if (element.type === "image") {
        return element.imageData ? (
            <img src={element.imageData} alt="" style={{width: "100%", height: "100%", objectFit: "contain", display: "block"}}/>
        ) : <span>Загрузите изображение</span>;
    }

    if (element.type === "lineItems") {
        return (
            <Box sx={{fontSize: 9, height: "100%"}}>
                <Box sx={{display: "grid", gridTemplateColumns: "2fr .7fr .8fr .8fr", bgcolor: element.color, color: "white", p: .7, fontWeight: 800}}>
                    <span>Позиция</span><span>Кол-во</span><span>Цена</span><span>Сумма</span>
                </Box>
                {["Товар A", "Товар B", "Товар C"].map((name, index) => (
                    <Box key={name} sx={{display: "grid", gridTemplateColumns: "2fr .7fr .8fr .8fr", p: .7, borderBottom: "1px solid #d8dee9", bgcolor: index % 2 ? "#f8fafc" : "white"}}>
                        <span>{name}</span><span>{index + 2} шт.</span><span>12,50</span><span>25,00</span>
                    </Box>
                ))}
            </Box>
        );
    }

    if (element.type === "total") {
        return <Box sx={{display: "flex", justifyContent: "space-between", alignItems: "center", height: "100%", px: 1.2, fontWeight: 900}}><span>ИТОГО</span><span>12 450,00 BYN</span></Box>;
    }

    if (element.type === "conditions") {
        return (
            <Box sx={{fontSize: 9}}>
                {["Валюта", "НДС", "Оплата", "Срок действия", "Поставка"].map((label) => (
                    <Box key={label} sx={{display: "grid", gridTemplateColumns: "35% 65%", borderBottom: "1px solid #d8dee9"}}>
                        <b style={{padding: 5, background: "#f4f6f8"}}>{label}</b>
                        <span style={{padding: 5}}>{label === "Валюта" ? "BYN" : "Значение из CRM"}</span>
                    </Box>
                ))}
            </Box>
        );
    }

    if (element.type === "divider") {
        return <Box sx={{height: "50%", borderBottom: `${Math.max(1, element.borderWidth)}px solid ${element.borderColor}`}}/>;
    }

    return <>{resolveSampleText(element) || "Пустой текст"}</>;
};

const CommercialOfferTemplateDesignerPage = () => {
    const navigate = useNavigate();
    const {templateId} = useParams();
    const isNew = !templateId || templateId === "new";
    const {data: savedTemplate, isLoading, isError} = useGetCommercialOfferTemplateQuery(templateId ?? "", {skip: isNew});
    const [createTemplate, {isLoading: creating}] = useCreateCommercialOfferTemplateMutation();
    const [updateTemplate, {isLoading: updating}] = useUpdateCommercialOfferTemplateMutation();
    const [name, setName] = useState("Персональное коммерческое предложение");
    const [description, setDescription] = useState("Фирменный многостраничный шаблон для персональных КП");
    const [document, setDocument] = useState<OfferTemplateDocument>(() => createDefaultOfferTemplate());
    const [activePage, setActivePage] = useState(1);
    const [selectedId, setSelectedId] = useState<string | null>(null);
    const [error, setError] = useState("");
    const initialized = useRef("");

    useEffect(() => {
        if (!savedTemplate || initialized.current === savedTemplate.concurrencyStamp) {
            return;
        }

        initialized.current = savedTemplate.concurrencyStamp;
        setName(savedTemplate.name);
        setDescription(savedTemplate.description);
        setDocument(savedTemplate.document);
        setActivePage(1);
        setSelectedId(null);
    }, [savedTemplate]);

    const selected = useMemo(
        () => document.elements.find((item) => item.id === selectedId) ?? null,
        [document.elements, selectedId],
    );

    const updateElement = (id: string, patch: Partial<OfferTemplateElement>) => {
        setDocument((current) => ({
            ...current,
            elements: current.elements.map((item) => item.id === id ? {...item, ...patch} : item),
        }));
    };

    const addElement = (type: OfferTemplateElementType) => {
        const next = createPaletteElement(type, activePage, document.elements.length + 1);
        setDocument((current) => ({...current, elements: [...current.elements, next]}));
        setSelectedId(next.id);
    };

    const duplicateSelected = () => {
        if (!selected) {
            return;
        }

        const duplicate: OfferTemplateElement = {
            ...selected,
            id: `${selected.type}-${Date.now()}`,
            x: clamp(selected.x + 18, 0, document.pageWidth - selected.width),
            y: clamp(selected.y + 18, 0, document.pageHeight - selected.height),
            zIndex: Math.max(...document.elements.map((item) => item.zIndex), 0) + 1,
        };
        setDocument((current) => ({...current, elements: [...current.elements, duplicate]}));
        setSelectedId(duplicate.id);
    };

    const deleteSelected = () => {
        if (!selected) {
            return;
        }

        setDocument((current) => ({...current, elements: current.elements.filter((item) => item.id !== selected.id)}));
        setSelectedId(null);
    };

    const beginInteraction = (
        event: React.PointerEvent,
        element: OfferTemplateElement,
        mode: "move" | "resize",
    ) => {
        event.preventDefault();
        event.stopPropagation();
        setSelectedId(element.id);
        const startX = event.clientX;
        const startY = event.clientY;
        const initial = {...element};

        const move = (pointer: PointerEvent) => {
            const dx = (pointer.clientX - startX) / CANVAS_SCALE;
            const dy = (pointer.clientY - startY) / CANVAS_SCALE;
            if (mode === "move") {
                updateElement(element.id, {
                    x: snap(clamp(initial.x + dx, 0, document.pageWidth - initial.width)),
                    y: snap(clamp(initial.y + dy, 0, document.pageHeight - initial.height)),
                });
            } else {
                updateElement(element.id, {
                    width: snap(clamp(initial.width + dx, 24, document.pageWidth - initial.x)),
                    height: snap(clamp(initial.height + dy, 12, document.pageHeight - initial.y)),
                });
            }
        };

        const stop = () => {
            window.removeEventListener("pointermove", move);
            window.removeEventListener("pointerup", stop);
        };
        window.addEventListener("pointermove", move);
        window.addEventListener("pointerup", stop);
    };

    const addPage = () => {
        setDocument((current) => ({...current, pageCount: current.pageCount + 1}));
        setActivePage(document.pageCount + 1);
        setSelectedId(null);
    };

    const removePage = () => {
        if (document.pageCount <= 1) {
            return;
        }

        setDocument((current) => ({
            ...current,
            pageCount: current.pageCount - 1,
            elements: current.elements
                .filter((item) => item.page !== activePage)
                .map((item) => item.page > activePage ? {...item, page: item.page - 1} : item),
        }));
        setActivePage(Math.max(1, activePage - 1));
        setSelectedId(null);
    };

    const uploadImage = (file?: File) => {
        if (!selected || !file) {
            return;
        }
        if (!/^image\/(png|jpeg)$/.test(file.type) || file.size > 4 * 1024 * 1024) {
            setError("Для PDF можно загрузить PNG или JPEG размером не более 4 МБ.");
            return;
        }

        const reader = new FileReader();
        reader.onload = () => updateElement(selected.id, {imageData: String(reader.result)});
        reader.readAsDataURL(file);
    };

    const save = async () => {
        if (name.trim().length < 2) {
            setError("Укажите название шаблона.");
            return;
        }

        setError("");
        try {
            if (isNew) {
                const created = await createTemplate({name: name.trim(), description: description.trim(), document}).unwrap();
                navigate(`/commercialOffers/templates/${created.id}`, {replace: true});
            } else if (savedTemplate && templateId) {
                const updated = await updateTemplate({
                    id: templateId,
                    body: {
                        concurrencyStamp: savedTemplate.concurrencyStamp,
                        name: name.trim(),
                        description: description.trim(),
                        document,
                    },
                }).unwrap();
                initialized.current = updated.concurrencyStamp;
            }
            toast.success("Шаблон сохранён.");
        } catch {
            setError("Не удалось сохранить шаблон. Проверьте границы элементов и уникальность названия.");
        }
    };

    if (!isNew && isLoading) {
        return <MainDiv><Typography>Загрузка шаблона…</Typography></MainDiv>;
    }

    if (!isNew && isError) {
        return <MainDiv><Alert severity="error">Шаблон не найден или недоступен этой компании.</Alert></MainDiv>;
    }

    const busy = creating || updating;

    return (
        <MainDiv>
            <PageHeader>
                <PageTitleGroup>
                    <Button startIcon={<ArrowBackOutlinedIcon/>} onClick={() => navigate("/commercialOffers/templates", {replace: true})} sx={{alignSelf: "start", px: 0}}>
                        Все шаблоны
                    </Button>
                    <PageTitle>{isNew ? "Новый шаблон КП" : name}</PageTitle>
                    <PageSubtitle>Перетаскивайте и растягивайте элементы прямо на листе. Координаты сохраняются на сервере в пунктах PDF.</PageSubtitle>
                </PageTitleGroup>
                <Button variant="contained" size="large" startIcon={<SaveOutlinedIcon/>} onClick={() => void save()} disabled={busy}>
                    {busy ? "Сохранение…" : "Сохранить шаблон"}
                </Button>
            </PageHeader>

            {error && <Alert severity="error" sx={{mb: 2}} onClose={() => setError("")}>{error}</Alert>}

            <Paper variant="outlined" sx={{p: 2, mb: 2}}>
                <Stack direction={{xs: "column", md: "row"}} spacing={2}>
                    <TextField label="Название" value={name} onChange={(event) => setName(event.target.value)} fullWidth/>
                    <TextField label="Описание" value={description} onChange={(event) => setDescription(event.target.value)} fullWidth/>
                </Stack>
            </Paper>

            <Box sx={{display: "grid", gridTemplateColumns: {xs: "1fr", xl: "250px minmax(540px, 1fr) 300px"}, gap: 2, alignItems: "start"}}>
                <Paper variant="outlined" sx={{p: 2}}>
                    <Typography fontWeight={900} mb={1.5}>Блоки</Typography>
                    <Stack spacing={1}>
                        <Button variant="outlined" startIcon={<TextFieldsOutlinedIcon/>} onClick={() => addElement("text")}>Текст / поле</Button>
                        <Button variant="outlined" startIcon={<AddPhotoAlternateOutlinedIcon/>} onClick={() => addElement("image")}>Изображение</Button>
                        <Button variant="outlined" startIcon={<TableRowsOutlinedIcon/>} onClick={() => addElement("lineItems")}>Таблица позиций</Button>
                        <Button variant="outlined" startIcon={<ReceiptLongOutlinedIcon/>} onClick={() => addElement("total")}>Итог</Button>
                        <Button variant="outlined" startIcon={<NotesOutlinedIcon/>} onClick={() => addElement("conditions")}>Условия</Button>
                        <Button variant="outlined" startIcon={<HorizontalRuleOutlinedIcon/>} onClick={() => addElement("divider")}>Разделитель</Button>
                    </Stack>
                    <Divider sx={{my: 2}}/>
                    <Typography fontWeight={900} mb={1}>Страницы</Typography>
                    <Stack direction="row" flexWrap="wrap" gap={1}>
                        {Array.from({length: document.pageCount}, (_, index) => index + 1).map((page) => (
                            <Button key={page} size="small" variant={page === activePage ? "contained" : "outlined"} onClick={() => { setActivePage(page); setSelectedId(null); }}>
                                {page}
                            </Button>
                        ))}
                    </Stack>
                    <Stack direction="row" gap={1} mt={1.5}>
                        <Button size="small" onClick={addPage} disabled={document.pageCount >= 12}>+ страница</Button>
                        <Button size="small" color="error" onClick={removePage} disabled={document.pageCount <= 1}>− страница</Button>
                    </Stack>
                </Paper>

                <Paper variant="outlined" sx={{p: 2, overflow: "auto", bgcolor: "#eef1f5", minHeight: 760}}>
                    <Box sx={{width: document.pageWidth * CANVAS_SCALE, height: document.pageHeight * CANVAS_SCALE, mx: "auto"}}>
                        <Box
                            onPointerDown={() => setSelectedId(null)}
                            sx={{
                                position: "relative",
                                width: document.pageWidth,
                                height: document.pageHeight,
                                transform: `scale(${CANVAS_SCALE})`,
                                transformOrigin: "top left",
                                bgcolor: "white",
                                boxShadow: "0 18px 50px rgba(21, 31, 49, .18)",
                                overflow: "hidden",
                                userSelect: "none",
                            }}
                        >
                            {document.elements.filter((item) => item.page === activePage).map((element) => {
                                const active = selectedId === element.id;
                                return (
                                    <Box
                                        key={element.id}
                                        onPointerDown={(event) => beginInteraction(event, element, "move")}
                                        sx={{
                                            position: "absolute",
                                            left: element.x,
                                            top: element.y,
                                            width: element.width,
                                            height: element.height,
                                            zIndex: element.zIndex,
                                            color: element.color,
                                            bgcolor: element.backgroundColor === "transparent" ? "transparent" : element.backgroundColor,
                                            border: `${element.borderWidth}px solid ${element.borderColor}`,
                                            borderRadius: `${element.borderRadius}px`,
                                            fontSize: element.fontSize,
                                            fontWeight: element.fontWeight === "bold" ? 800 : 400,
                                            textAlign: element.textAlign,
                                            whiteSpace: "pre-wrap",
                                            overflow: "hidden",
                                            cursor: "move",
                                            outline: active ? "2px solid #2563eb" : "none",
                                            outlineOffset: 2,
                                            boxSizing: "border-box",
                                            p: element.type === "text" ? .5 : 0,
                                        }}
                                    >
                                        {active && <DragIndicatorOutlinedIcon sx={{position: "absolute", top: 1, right: 1, fontSize: 16, opacity: .55}}/>}
                                        <ElementPreview element={element}/>
                                        {active && (
                                            <Box
                                                onPointerDown={(event) => beginInteraction(event, element, "resize")}
                                                sx={{position: "absolute", right: 0, bottom: 0, width: 14, height: 14, bgcolor: "#2563eb", cursor: "nwse-resize"}}
                                            />
                                        )}
                                    </Box>
                                );
                            })}
                        </Box>
                    </Box>
                </Paper>

                <Paper variant="outlined" sx={{p: 2}}>
                    <Stack direction="row" justifyContent="space-between" alignItems="center" mb={1.5}>
                        <Typography fontWeight={900}>Свойства</Typography>
                        {selected && (
                            <Stack direction="row">
                                <Tooltip title="Дублировать"><IconButton size="small" onClick={duplicateSelected}><ContentCopyOutlinedIcon fontSize="small"/></IconButton></Tooltip>
                                <Tooltip title="Удалить"><IconButton size="small" color="error" onClick={deleteSelected}><DeleteOutlineOutlinedIcon fontSize="small"/></IconButton></Tooltip>
                            </Stack>
                        )}
                    </Stack>
                    {!selected && <Typography color="text.secondary">Выберите элемент на листе.</Typography>}
                    {selected && (
                        <Stack spacing={1.5}>
                            <Typography variant="caption" color="text.secondary">{elementLabels[selected.type]}</Typography>
                            {selected.type === "text" && (
                                <>
                                    <TextField select size="small" label="Источник значения" value={selected.binding} onChange={(event) => updateElement(selected.id, {binding: event.target.value})}>
                                        {bindings.map(([value, label]) => <MenuItem key={value || "static"} value={value}>{label}</MenuItem>)}
                                    </TextField>
                                    {!selected.binding && (
                                        <TextField multiline minRows={4} label="Текст" value={selected.content} onChange={(event) => updateElement(selected.id, {content: event.target.value})} helperText="Можно вставлять {{customer.name}} и другие поля."/>
                                    )}
                                </>
                            )}
                            {selected.type === "image" && (
                                <Button component="label" variant="outlined" startIcon={<AddPhotoAlternateOutlinedIcon/>}>
                                    Загрузить PNG/JPEG
                                    <input hidden type="file" accept="image/png,image/jpeg" onChange={(event) => uploadImage(event.target.files?.[0])}/>
                                </Button>
                            )}
                            <Stack direction="row" spacing={1}>
                                <TextField size="small" type="number" label="X" value={selected.x} onChange={(event) => updateElement(selected.id, {x: Number(event.target.value)})}/>
                                <TextField size="small" type="number" label="Y" value={selected.y} onChange={(event) => updateElement(selected.id, {y: Number(event.target.value)})}/>
                            </Stack>
                            <Stack direction="row" spacing={1}>
                                <TextField size="small" type="number" label="Ширина" value={selected.width} onChange={(event) => updateElement(selected.id, {width: Number(event.target.value)})}/>
                                <TextField size="small" type="number" label="Высота" value={selected.height} onChange={(event) => updateElement(selected.id, {height: Number(event.target.value)})}/>
                            </Stack>
                            {selected.type !== "image" && selected.type !== "divider" && (
                                <>
                                    <TextField size="small" type="number" label="Размер шрифта" value={selected.fontSize} onChange={(event) => updateElement(selected.id, {fontSize: Number(event.target.value)})}/>
                                    <TextField select size="small" label="Начертание" value={selected.fontWeight} onChange={(event) => updateElement(selected.id, {fontWeight: event.target.value as "regular" | "bold"})}>
                                        <MenuItem value="regular">Обычное</MenuItem>
                                        <MenuItem value="bold">Жирное</MenuItem>
                                    </TextField>
                                    <TextField select size="small" label="Выравнивание" value={selected.textAlign} onChange={(event) => updateElement(selected.id, {textAlign: event.target.value as "left" | "center" | "right"})}>
                                        <MenuItem value="left">Слева</MenuItem>
                                        <MenuItem value="center">По центру</MenuItem>
                                        <MenuItem value="right">Справа</MenuItem>
                                    </TextField>
                                </>
                            )}
                            <Stack direction="row" spacing={1}>
                                <TextField size="small" type="color" label="Текст" value={selected.color} onChange={(event) => updateElement(selected.id, {color: event.target.value})} InputLabelProps={{shrink: true}}/>
                                <TextField size="small" type="color" label="Фон" value={selected.backgroundColor === "transparent" ? "#ffffff" : selected.backgroundColor} onChange={(event) => updateElement(selected.id, {backgroundColor: event.target.value})} InputLabelProps={{shrink: true}}/>
                            </Stack>
                            <Stack direction="row" spacing={1}>
                                <TextField size="small" type="color" label="Рамка" value={selected.borderColor} onChange={(event) => updateElement(selected.id, {borderColor: event.target.value})} InputLabelProps={{shrink: true}}/>
                                <TextField size="small" type="number" label="Толщина" value={selected.borderWidth} onChange={(event) => updateElement(selected.id, {borderWidth: Number(event.target.value)})}/>
                            </Stack>
                            <TextField size="small" type="number" label="Скругление" value={selected.borderRadius} onChange={(event) => updateElement(selected.id, {borderRadius: Number(event.target.value)})}/>
                            <Typography variant="caption" color="text.secondary">
                                Предпросмотр: {selected.binding ? sampleBindingValues[selected.binding] : elementLabels[selected.type]}
                            </Typography>
                        </Stack>
                    )}
                </Paper>
            </Box>
        </MainDiv>
    );
};

export default CommercialOfferTemplateDesignerPage;
