export const createPaletteElement = (
    type: OfferTemplateElementType,
    page: number,
    order: number,
): OfferTemplateElement => {
    const id = `${type}-${Date.now()}-${order}`;
    const base = element(id, type, page, 60 + (order % 5) * 14, 90 + (order % 8) * 18, 260, 72);

    switch (type) {
        case "text":
            return {...base, content: "Новый текст", fontSize: 16};
        case "image":
            return {...base, imageData: TRANSPARENT_IMAGE, width: 220, height: 140, borderWidth: 1};
        case "lineItems":
            return {...base, width: 475, height: 260, fontSize: 9, borderWidth: 1};
        case "total":
            return {...base, width: 475, height: 54, fontSize: 14, fontWeight: "bold", backgroundColor: "#eaf4ec", borderWidth: 1};
        case "conditions":
            return {...base, width: 475, height: 165, fontSize: 9, borderWidth: 1};
        case "divider":
            return {...base, width: 475, height: 12, borderWidth: 1};
    }
};

