export const resolveSampleText = (element: OfferTemplateElement) => {
    if (element.binding) {
        return sampleBindingValues[element.binding] ?? "Динамическое значение";
    }

    return element.content.replace(/\{\{\s*([a-zA-Z0-9.]+)\s*\}\}/g, (_match, key) => sampleBindingValues[key] ?? "");
};
